TLM.f("Tempora/Pasc3-0r",{"officium":"Dominica III Post Pascha","rule":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 65:1-2"},{"k":"text","la":"Jubiláte Deo, omnis terra, allelúja: psalmum dícite nómini ejus, allelúja: date glóriam laudi ejus, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 65:3"},{"k":"text","la":"Dícite Deo, quam terribília sunt ópera tua, Dómine! in multitúdine virtútis tuæ mentiéntur tibi inimíci tui."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Jubiláte Deo, omnis terra, allelúja: psalmum dícite nómini ejus, allelúja: date glóriam laudi ejus, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui errántibus, ut in viam possint redíre justítiæ, veritátis tuæ lumen osténdis: da cunctis, qui christiána professióne censéntur, et illa respúere, quæ huic inimíca sunt nómini; et ea, quæ sunt apta, sectári."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 2:11-19"},{"k":"text","la":"Caríssimi: Obsecro vos tamquam ádvenas et peregrínos abstinére vos a carnálibus desidériis, quæ mílitant advérsus ánimam, conversatiónem vestram inter gentes habéntes bonam: ut in eo, quod detréctant de vobis tamquam de malefactóribus, ex bonis opéribus vos considerántes, gloríficent Deum in die visitatiónis. Subjécti ígitur estóte omni humánæ creatúræ propter Deum: sive regi, quasi præcellénti: sive dúcibus, tamquam ab eo missis ad vindíctam malefactórum, laudem vero bonórum: quia sic est volúntas Dei, ut benefaciéntes obmutéscere faciátis imprudéntium hóminum ignorántiam: quasi líberi, et non quasi velámen habéntes malítiæ libertátem, sed sicut servi Dei. Omnes honoráte: fraternitátem dilígite: Deum timéte: regem honorificáte. Servi, súbditi estóte in omni timóre dóminis, non tantum bonis et modéstis, sed étiam dýscolis. Hæc est enim grátia: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 110:9"},{"k":"text","la":"Redemptiónem misit Dóminus pópulo suo. Allelúja."},{"k":"ref","la":"Luc 24:46"},{"k":"text","la":"Oportébat pati Christum, et resúrgere a mórtuis: et ita intráre in glóriam suam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 16:16-22"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Módicum, et jam non vidébitis me: et íterum módicum, et vidébitis me: quia vado ad Patrem. Dixérunt ergo ex discípulis ejus ad ínvicem: Quid est hoc, quod dicit nobis: Módicum, et non vidébitis me: et íterum módicum, et vidébitis me, et quia vado ad Patrem? Dicébant ergo: Quid est hoc, quod dicit: Módicum? nescímus, quid lóquitur. Cognóvit autem Jesus, quia volébant eum interrogáre, et dixit eis: De hoc quǽritis inter vos, quia dixi: Módicum, et non vidébitis me: et íterum módicum, et vidébitis me. Amen, amen, dico vobis: quia plorábitis et flébitis vos, mundus autem gaudébit: vos autem contristabímini, sed tristítia vestra vertétur in gáudium. Múlier cum parit, tristítiam habet, quia venit hora ejus: cum autem pepérerit púerum, jam non méminit pressúræ propter gáudium, quia natus est homo in mundum. Et vos ígitur nunc quidem tristítiam habétis, íterum autem vidébo vos, et gaudébit cor vestrum: et gáudium vestrum nemo tollet a vobis."}],"Offertorium":[{"k":"ref","la":"Ps 145:2"},{"k":"text","la":"Lauda, ánima mea, Dóminum: laudábo Dóminum in vita mea: psallam Deo meo, quámdiu ero, allelúja."}],"Secreta":[{"k":"text","la":"His nobis, Dómine, mystériis conferátur, quo, terréna desidéria mitigántes, discámus amáre cœléstia."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 16:16"},{"k":"text","la":"Módicum, et non vidébitis me, allelúja: íterum módicum, et vidébitis me, quia vado ad Patrem, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Sacraménta quæ súmpsimus, quǽsumus, Dómine: et spirituálibus nos instáurent aliméntis, et corporálibus tueántur auxíliis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"82f7c8c90fbb5faa":{"t":"Ps 65, 1-2, Ps 65, 3\n(Ps 65, 1-2) Kličite Bogu, sve zemlje, <i>aleluja</i>!\nPjevajte pjesmu imenu njegovu, <i>aleluja</i>!\nProglasite njegovu slavu, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 65, 3) Recite Bogu: Kako su silna tvoja djela, Gospodine! Zbog mnoštva tvoje snage laskaju ti neprijatelji tvoji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 65, 1-2) Kličite Bogu, sve zemlje, <i>aleluja</i>!\nPjevajte pjesmu imenu njegovu, <i>aleluja</i>!\nProglasite njegovu slavu, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>."},"de6caf65ade0d16d":{"t":"<i>Pomolimo se</i>.\nBože, koji zalutalima pokazuješ svjetlo svoje istine da se mogu vratiti na put pravednosti, daj svima koji ispovijedaju kršćansku vjeru, da odbace ono što se protivi ovome imenu, a da teže za onim što mu dolikuje.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"46b42bfef1fe1b45":{"t":"1 Pt 2, 11-19\nČitanje Poslanice bl. Petra apostola. Predragi: Molim vas da se kao stranci i putnici uzdržavate od tjelesnih požuda koje vojuju protiv duše. Vaše vladanje među nevjernicima neka bude dolično, da bi po onome zbog čega vas kleveću kao zločince, motreći vaša dobra djela, slavili Boga u dan pohođenja. – Stoga, pokoravajte se radi Boga svakoj ljudskoj uredbi: bilo vladaru kao najodličnijemu, bilo upraviteljima koje on šalje, da kazni zle, a zaštiti dobre. To je naime volja Božja, da neznanje bezumnika ušutkate dobrim djelima. Vladajte se kao slobodni, ali ne kao oni koji slobodom prikrivaju zloću, nego kao sluge Božje! – Poštujte svakoga, ljubite braću, Boga se bojte, poštujte vladara! Sluge, s dužnim poštovanjem pokoravajte se ne samo dobrim i blagim gospodarima, nego i zločestima. Ovo je naime milost u Gospodinu našem Isusu Kristu."},"94a6e099d6178b3c":{"t":"Ps 110, 9, Lk 24, 46\n<i>Aleluja</i>, <i>aleluja</i>.\n(Ps 110, 9) Otkupljenje posla Gospodin narodu svome, <i>aleluja</i>.\n(Lk 24, 46) Trebalo je da Krist i trpi i uskrsne od mrtvih i da tako uđe u svoju slavu, <i>aleluja</i>."},"46056db6f7d972b4":{"t":"Iv 16, 16-22\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: Reče Isus svojim učenicima: Još malo i više me nećete vidjeti, i opet malo, pa ćete me vidjeti, jer idem Ocu. A neki od učenika rekoše među sobom: Što je to što nam kaže: Još malo i i više me nećete vidjeti i opet malo, pa ćete me vidjeti, jer idem Ocu? Pitali su: Što znači to što kaže: Još malo? Ne znamo što time hoće da kaže. Isus je znao da su ga htjeli pitati, pa im reče: Pitate se među sobom za ono što sam rekao: Još malo i nećete me vidjeti, i opet malo, pa ćete me vidjeti. Zaista vam kažem, da ćete vi plakati i tugovati, a svijet će se radovati. Vi ćete se žalostiti, ali će se vaša žalost pretvoriti u radost. Žena kad rađa, žalosna je, jer joj je došao čas, ali kad rodi dijete, više se ne sjeća muke od radosti, što se čovjek rodio na svijet. Tako ste i vi sada žalosni, ali ću vas opet vidjeti, pa će se radovati vaše srce i vaše radosti nitko vam neće oduzeti."},"0f89e89f1130bcea":{"t":"Ps 145, 2\nHvali, dušo moja, Gospodina! Hvalit ću Gospodina za života svojega! Pjevat ću Bogu svojemu dok me bude, <i>aleluja</i>."},"ba9d873d4fb1e987":{"t":"Po ovim nam otajstvima, Gospodine, daj da krotimo zemaljske želje i naučimo ljubiti nebesko.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"dd1874b999fa5359":{"t":"Iv 16, 16\nJoš malo i više me nećete vidjeti i opet malo pa ćete me vidjeti, jer idem Ocu, <i>aleluja</i>, <i>aleluja</i>."},"c9bdd65cc0626273":{"t":"<i>Pomolimo se</i>.\nOtajstva koja primismo, molimo, Gospodine, okrijepila nas duhovnom hranom i bila nam na tjelesnu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
